// gen applies, one at a time, the syntactic mutations of one Go file, runs a
// test command for each, and puts the file back.
package main

import (
	"bytes"
	"context"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"os/signal"
	"strconv"
	"strings"
	"time"
)

type mutant struct {
	start, end int
	repl       string
	desc       string
	line       int
}

var swap = map[token.Token]token.Token{
	token.EQL: token.NEQ, token.NEQ: token.EQL,
	token.LSS: token.LEQ, token.LEQ: token.LSS,
	token.GTR: token.GEQ, token.GEQ: token.GTR,
	token.LAND: token.LOR, token.LOR: token.LAND,
	token.ADD: token.SUB, token.SUB: token.ADD,
	token.INC: token.DEC, token.DEC: token.INC,
	token.ADD_ASSIGN: token.SUB_ASSIGN, token.SUB_ASSIGN: token.ADD_ASSIGN,
}

func main() {
	file := flag.String("file", "", "the Go file to mutate")
	list := flag.Bool("list", false, "only list the mutants")
	only := flag.String("lines", "", "only mutate these lines (a,b-c)")
	flag.Parse()
	src, err := os.ReadFile(*file)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, *file, src, 0)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
	var ms []mutant
	add := func(pos token.Pos, n int, repl, desc string) {
		p := fset.Position(pos)
		ms = append(ms, mutant{p.Offset, p.Offset + n, repl, desc, p.Line})
	}
	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.BinaryExpr:
			if t, ok := swap[x.Op]; ok {
				add(x.OpPos, len(x.Op.String()), t.String(), x.Op.String()+" -> "+t.String())
			}
		case *ast.IncDecStmt:
			add(x.TokPos, 2, swap[x.Tok].String(), x.Tok.String()+" -> "+swap[x.Tok].String())
		case *ast.AssignStmt:
			if t, ok := swap[x.Tok]; ok {
				add(x.TokPos, len(x.Tok.String()), t.String(), x.Tok.String()+" -> "+t.String())
			}
		case *ast.UnaryExpr:
			if x.Op == token.NOT {
				add(x.OpPos, 1, "", "drop !")
			}
		case *ast.Ident:
			if x.Name == "true" || x.Name == "false" {
				r := map[string]string{"true": "false", "false": "true"}[x.Name]
				add(x.Pos(), len(x.Name), r, x.Name+" -> "+r)
			}
		case *ast.BasicLit:
			if x.Kind == token.INT {
				v, err := strconv.Atoi(x.Value)
				if err == nil {
					add(x.Pos(), len(x.Value), strconv.Itoa(v+1), x.Value+" -> "+strconv.Itoa(v+1))
					add(x.Pos(), len(x.Value), strconv.Itoa(v-1), x.Value+" -> "+strconv.Itoa(v-1))
				}
			}
		case *ast.GenDecl:
			if x.Tok == token.IMPORT {
				return false
			}
		}
		return true
	})
	keep := lineFilter(*only)
	cmd := flag.Args()
	if *list {
		for _, m := range ms {
			if keep(m.line) {
				fmt.Printf("%s:%d: %s\n", *file, m.line, m.desc)
			}
		}
		return
	}
	restore := func() { _ = os.WriteFile(*file, src, 0o644) }
	defer restore()
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, os.Interrupt)
	go func() { <-sig; restore(); os.Exit(130) }()
	if out, err := run(cmd); err != nil {
		fmt.Fprintf(os.Stderr, "the tests fail before any mutation:\n%s", out)
		os.Exit(2)
	}
	survived := 0
	for _, m := range ms {
		if !keep(m.line) {
			continue
		}
		mut := append(append(append([]byte{}, src[:m.start]...), m.repl...), src[m.end:]...)
		if err := os.WriteFile(*file, mut, 0o644); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return
		}
		out, err := run(cmd)
		restore()
		label := fmt.Sprintf("%s:%d: %s", *file, m.line, m.desc)
		switch {
		case err == nil:
			survived++
			fmt.Println("SURVIVED:", label)
		case bytes.Contains(out, []byte("build failed")) || bytes.Contains(out, []byte("setup failed")) || bytes.Contains(out, []byte("vet:")):
			fmt.Println("not compiled:", label)
		case bytes.Contains(out, []byte("panic: test timed out")):
			fmt.Println("killed (timeout):", label)
		default:
			fmt.Println("killed:", label)
		}
	}
	fmt.Printf("survived %d\n", survived)
}

func run(cmd []string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	c := exec.CommandContext(ctx, cmd[0], cmd[1:]...)
	return c.CombinedOutput()
}

func lineFilter(s string) func(int) bool {
	if s == "" {
		return func(int) bool { return true }
	}
	set := map[int]bool{}
	for _, part := range strings.Split(s, ",") {
		a, b, ok := strings.Cut(part, "-")
		x, _ := strconv.Atoi(a)
		y := x
		if ok {
			y, _ = strconv.Atoi(b)
		}
		for i := x; i <= y; i++ {
			set[i] = true
		}
	}
	return func(l int) bool { return set[l] }
}
