// spec applies the mutations listed in a file, one at a time, runs a test
// command for each, and puts the file back. A line of the list is
// name | file | old | new, where ⏎ is a line feed and ⇥ a tab.
package main

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

func unesc(s string) string {
	return strings.NewReplacer("⏎", "\n", "⇥", "\t").Replace(s)
}

func run(cmd []string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()
	return exec.CommandContext(ctx, cmd[0], cmd[1:]...).CombinedOutput()
}

func main() {
	list, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	cmd := os.Args[2:]
	if out, err := run(cmd); err != nil {
		fmt.Printf("baseline fails:\n%s", out)
		os.Exit(2)
	}
	for _, line := range strings.Split(string(list), "\n") {
		if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, " | ")
		if len(f) != 4 {
			fmt.Println("BAD LINE:", line)
			continue
		}
		name, file, old, repl := f[0], f[1], unesc(f[2]), unesc(f[3])
		src, err := os.ReadFile(file)
		if err != nil {
			fmt.Println("BAD FILE:", name, err)
			continue
		}
		if c := strings.Count(string(src), old); c != 1 {
			fmt.Printf("BAD OLD (%d places): %s\n", c, name)
			continue
		}
		_ = os.WriteFile(file, []byte(strings.Replace(string(src), old, repl, 1)), 0o644)
		out, err := run(cmd)
		_ = os.WriteFile(file, src, 0o644)
		switch {
		case err == nil:
			fmt.Println("SURVIVED:", name)
		case bytes.Contains(out, []byte("build failed")) || bytes.Contains(out, []byte("setup failed")):
			fmt.Println("not compiled:", name)
			for _, l := range strings.Split(string(out), "\n") {
				if strings.Contains(l, ".go:") {
					fmt.Println("   ", l)
					break
				}
			}
		default:
			var fails []string
			for _, l := range strings.Split(string(out), "\n") {
				if strings.HasPrefix(l, "--- FAIL") {
					fails = append(fails, strings.Fields(l)[2])
				}
			}
			fmt.Printf("killed: %s %v\n", name, fails)
		}
	}
}
